        /// <summary>
        /// Registers any routes required by the application.
        /// </summary>
        protected virtual void RegisterAllRoutes()
        {
            var routes = RouteTable.Routes;
            if (RouteRegistrars == null || RouteRegistrars.Count() == 0)
                return;


            var registrars = RouteRegistrars
                .OrderBy(lazy => lazy.Metadata.Order)
                .Select(lazy => lazy);

            //registrars.ForEach(r => r.RegisterIgnoreRoutes(routes));
            //registrars.ForEach(r => r.RegisterRoutes(routes));

            if (CurrentModules == null)
            {
                Logger.Info("Inicio do registro dos módulos");
                CurrentModules = new Dictionary<string, ModuleInfo>();

                registrars.ForEach(r =>
                {
                    ModuleInfo moduleInfo = new ModuleInfo();
                    moduleInfo.AssemblyName = r.Value.GetType().Assembly.FullName.Split(',')[0];
                    moduleInfo.AssemblyVersion = r.Value.GetType().Assembly.GetName().Version.ToString();
                    moduleInfo.AssemblyVersionURL = r.Value.GetType().Assembly.GetName().Version.ToString().Replace(".", "-");

                    moduleInfo.ModuleUId = r.Metadata.ModuleId;
                    moduleInfo.ModuleName = moduleInfo.AssemblyName.Replace(".", "-").ToLower();
                    moduleInfo.ModuleOrder = r.Metadata.Order;

                    if (String.IsNullOrEmpty(r.Metadata.ShellVersion))
                        moduleInfo.ShellAssemblyVersion = "0.0.0";
                    else
                    {
                        Version version = new Version(r.Metadata.ShellVersion);
                        moduleInfo.ShellAssemblyVersion = string.Format("{0}.{1}.{2}", version.Major, version.Minor, version.Build);
                    }

                    moduleInfo.AssemblyType = Common.IsAssemblyDebugBuild(r.Value.GetType().Assembly);
                    if (moduleInfo.ModuleOrder == -1)
                    {
                        moduleInfo.IsModuleShell = true;
                        moduleInfo.ShellAssemblyVersion = moduleInfo.AssemblyVersion;

                        ShellModule = moduleInfo;
                    }
                    
                    moduleInfo.ModuleNamePath = moduleInfo.ModuleName;
                    moduleInfo.AssemblyVersionPath = string.Concat("v", moduleInfo.AssemblyVersionURL, "-", moduleInfo.AssemblyType);
                    moduleInfo.BuildDate = Common.GetBuildDateTime(r.Value.GetType().Assembly);

                    if (CurrentModules.ContainsKey(moduleInfo.ModuleUId))
                    {
                        Logger.Warn("Modulo ja registrado '{0}' '{1}', '{2}'", moduleInfo.ModuleName, moduleInfo.ModuleUId, moduleInfo.AssemblyName);
                    }
                    else
                    {
                        CurrentModules.Add(moduleInfo.ModuleUId, moduleInfo);
                        Logger.Info("Registrando o modulo '{0}', '{1}', '{2}'", moduleInfo.ModuleName, moduleInfo.ModuleUId, moduleInfo.AssemblyName);
                    }

                });
            }


            registrars.ForEach(r =>
            {
                var crc32Files = new StringBuilder();
                var moduleName = CurrentModules[r.Metadata.ModuleId].ModuleName;

                var loadedEmbeddedResources = r.Value.LoadEmbeddedResources(moduleName);
                foreach (var e in loadedEmbeddedResources)
                {
                    if (EmbeddedResources.ContainsKey(e.Key))
                    {
                        Logger.Warn("Recurso ja adicionado do modulo '{0}' arquivo '{1}'", moduleName, e.Key);
                        EmbeddedResources.Add(e.Key, e.Value);
                    }
                    else
                    {
                        Logger.Info("Adicionando o recurso do modulo '{0}' arquivo '{1}'", moduleName, e.Key);
                        EmbeddedResources.Add(e.Key, e.Value);
                        crc32Files.Append(e.Value.CRC32);
                    }
                }

                CurrentModules[r.Metadata.ModuleId].CRC32 = Linx.Internet.Application.Common.ParallelCRC.Compute(crc32Files.ToArrayBytes()).ToString("x2").ToUpper();
            });

        }


        /// <summary>
        /// Registers any routes required by the application.
        /// </summary>
        protected virtual void RegisterAllRepository()
        {
            if (RepositoryRegistrars == null || RepositoryRegistrars.Count() == 0)
                return;


            var registrars = RepositoryRegistrars
                .OrderBy(lazy => lazy.Metadata.Order)
                .Select(lazy => lazy.Value);


            registrars.ForEach(r =>
            {
                var loadedRepositoryResources = r.LoadRepository();
                foreach (var e in loadedRepositoryResources)
                {
                    RepositoryResources.Add(e.Key, e.Value);
                }
            });
        }

        ///// <summary>
        ///// Registers any routes required by the application.
        ///// </summary>
        protected virtual void RegisterAllServiceRoutes()
        {
            var routes = RouteTable.Routes;
            if (ServiceRegistrars == null || ServiceRegistrars.Count() == 0)
                return;


            var registrars = ServiceRegistrars
                .OrderBy(lazy => lazy.Metadata.Order)
                .Select(lazy => lazy.Value);

            registrars.ForEach(r => r.RegisterType());
        }

        /// <summary>
        /// Registers any routes required by the application.
        /// </summary>
        protected virtual void RegisterAllHandles()
        {
            var routes = RouteTable.Routes;
            CurrentHandles = new Dictionary<string, dynamic>();

            if (HandleRegistrars == null || HandleRegistrars.Count() == 0)
                return;

            var registrars = HandleRegistrars
                .Select(lazy => lazy);

            registrars.ForEach(r =>
            {
                CurrentHandles.Add( r.Value.ToString().ToLower(), r.Value);
                RouteTable.Routes.Add(new Route
                (
                    "handler.axd",
                    new RouteValueDictionary(new { id = r.Value.ToString().ToLower() }),
                    r.Value as IRouteHandler
                ));
            });



        }

        /// <summary>
        /// Maps the specified virtual path.
